let cid = msg.chargerId;

const smartConf = (global.get('smartParkingConfig', 'default') || global.get('smartParkingConfig')) || {CHARGERS:{}};
let conf = smartConf.CHARGERS[cid];
if (!conf && cid) {
    if (smartConf.CHARGERS[cid + '_1']) {
        conf = smartConf.CHARGERS[cid + '_1'];
        cid = cid + '_1';
        msg.chargerId = cid;
    } else if (cid.endsWith('_1') && smartConf.CHARGERS[cid.slice(0, -2)]) {
        conf = smartConf.CHARGERS[cid.slice(0, -2)];
        cid = cid.slice(0, -2);
        msg.chargerId = cid;
    }
}
if (!conf) return msg;

let currentAmp = msg.amp !== undefined ? msg.amp : (conf ? conf.amp : 16);
const statesCache = flow.get('last_ui_states') || {};
const oldState = statesCache[cid] || {};
const ampChanged = (oldState.amp !== undefined && Number(oldState.amp) !== Number(currentAmp));

if (msg.info && typeof msg.info === 'string' && msg.info.toLowerCase().includes('error')) {
    let dcTime = flow.get('goe_dc_time_' + cid) || 0;
    let isOffline = flow.get('goe_is_offline_' + cid) || false;

    if (!dcTime) {
        flow.set('goe_dc_time_' + cid, Date.now());
        return null;
    } else if (Date.now() - dcTime <= 10000) {
        return null;
    } else {
        if (isOffline) {
            return null;
        } else {
            flow.set('goe_is_offline_' + cid, true);
            // flow.set('goe_current_user_' + cid, '');
            msg.payload = { occupied: false, power: 0, name: 'Offline / API Error', zoneId: conf.zone, spot: conf.spot, isOffline: true };
            return [msg, null, null];
        }
    }
}

const r = msg.payload;
if (!r || !Array.isArray(r) || r.length < 21) return null;

let rawCar = r[2];
let allowCharging = r[3];
let rawPwr = r[20];

let currentName = flow.get('goe_current_user_' + cid) || 'Charging...';
let currentCard = flow.get('goe_current_card_' + cid) || '';
let notifUser = currentName + (currentCard ? ' (' + currentCard + ')' : '');

let physicallyOccupied = (rawCar >= 2 && rawCar <= 4);

let dcTime = flow.get('goe_dc_time_' + cid) || 0;
let isOffline = flow.get('goe_is_offline_' + cid) || false;

flow.set('goe_dc_time_' + cid, 0);
flow.set('goe_is_offline_' + cid, false);

let starting = flow.get('goe_starting_session_' + cid) || false;
if (rawCar === 2) {
    flow.set('goe_starting_session_' + cid, false);
    starting = false;
}

if (!physicallyOccupied) {
    flow.set('goe_current_user_' + cid, '');
    flow.set('goe_starting_session_' + cid, false);
    currentName = '';
    starting = false;
}

let occupied = physicallyOccupied;

let sessionEnergy = 0;
if (occupied) {
    let lastTs = flow.get('goe_energy_ts_' + cid);
    let curEnergy = flow.get('goe_session_energy_' + cid) || 0;
    let nowTs = Date.now();
    if (lastTs && lastTs > 0) {
        let dtHours = (nowTs - lastTs) / 3600000.0;
        let powerKW = rawPwr / 1000.0;
        curEnergy += powerKW * dtHours;
    }
    flow.set('goe_energy_ts_' + cid, nowTs);
    flow.set('goe_session_energy_' + cid, curEnergy);
    sessionEnergy = curEnergy;
} else {
    flow.set('goe_energy_ts_' + cid, 0);
    flow.set('goe_session_energy_' + cid, 0);
}

const prevNotifStatus = flow.get('goe_notif_status_' + cid) || 0;
flow.set('goe_notif_status_' + cid, rawCar);
flow.set('goe_status_' + cid, rawCar);
flow.set('goe_allow_charging_' + cid, allowCharging);

let autoStartMsg = null;
let notificationToast = null;

if (prevNotifStatus !== 2 && rawCar === 2) {
    notificationToast = { payload: { type: 'rfid_notification', text: 'Go-e: Charging started.', user: notifUser } };
} else if (prevNotifStatus === 2 && rawCar !== 2) {
    notificationToast = { payload: { type: 'rfid_notification', text: 'Go-e: Charging stopped.', user: notifUser } };
}



if (occupied && rawCar === 3) {
    const pendingTime = flow.get('goe_auth_pending_time_' + cid) || 0;
    const pendingUser = flow.get('goe_auth_pending_user_' + cid) || '';
    const pendingCard = flow.get('goe_auth_pending_card_' + cid) || '';
    if (pendingUser && (Date.now() - pendingTime < 60000)) {
        flow.set('goe_auth_pending_time_' + cid, 0);
        flow.set('goe_auth_pending_user_' + cid, '');
        flow.set('goe_current_user_' + cid, pendingUser);
        flow.set('goe_current_card_' + cid, pendingCard);
        flow.set('goe_starting_session_' + cid, true);
        autoStartMsg = { payload: { fc: 16, unitid: 1, address: 201, value: [0], quantity: 1 }, chargerId: cid };
        notificationToast = { payload: { type: 'rfid_notification', text: 'Go-e: Vehicle connected. Starting charge...', user: pendingUser + (pendingCard ? ' (' + pendingCard + ')' : '') } };
        currentName = pendingUser;
    }
}

const statusLabels = { 1: 'Idle', 2: 'Charging', 3: (allowCharging === 1 ? 'Connected' : (starting ? 'Starting' : 'WaitCar')), 4: (allowCharging === 1 ? 'Connected' : (starting ? 'Starting' : 'Complete')), 5: 'Error', 65535: 'No Data' };
const carsConfig = global.get('carsConfig', 'default') || {};

const cConf = carsConfig[(conf ? conf.zone : '1A') + '-' + (conf ? conf.spot : 2)] || {};
const finalName  = cConf.name ? cConf.name : (currentName || statusLabels[rawCar] || 'Status ' + rawCar);
const finalColor = cConf.color ? cConf.color : '#3b7ef8';

msg.payload = { occupied: occupied, power: rawPwr / 1000.0, powerW: rawPwr, energy: 0, sessionEnergy: sessionEnergy, amp: currentAmp, name: finalName, color: finalColor, zoneId: (conf ? conf.zone : '1A'), spot: (conf ? conf.spot : 2), raw_status: rawCar, status_label: statusLabels[rawCar] || 'Status ' + rawCar, isCharged: (rawCar === 4 && allowCharging === 0 && !starting), isOffline: false, activeCard: currentCard, activeUser: currentName };

return [msg, autoStartMsg, notificationToast];

const SEED_CONFIG = {
    FLOORS: [
        { id: '2B', cars: 6 }, { id: '2A', cars: 4 },
        { id: '1B', cars: 6 }, { id: '1A', cars: 4 }
    ],
    CHARGERS: {
        'victron_1': { zone: '1B', spot: 1 },
        'easee_1': { zone: '1A', spot: 1 },
        'goe_1': { zone: '1A', spot: 2 }
    },
    USERS: {
        '5A61CA0003': { name: 'Victron User', charger: 'victron_1', zone: '1B', spot: 1 },
        '5561CA0003': { name: 'Easee User', charger: 'easee_1', zone: '1A', spot: 1 },
        '0401020304': { name: 'Go-E User', charger: 'goe_1', zone: '1A', spot: 2 }
    }
};

function resolveDataDir() {
    const candidates = [
        '/home/smartev/.node-red',
        '/home/pi/.node-red',
        '/root/.node-red',
        '/data'
    ];
    if (typeof RED !== 'undefined' && RED.settings && RED.settings.userDir) {
        candidates.unshift(RED.settings.userDir);
    }
    for (let i = 0; i < candidates.length; i++) {
        try {
            if (!fs.existsSync(candidates[i])) {
                fs.mkdirSync(candidates[i], { recursive: true });
            }
            fs.accessSync(candidates[i], fs.constants.W_OK);
            return candidates[i];
        } catch (e) { }
    }
    return '/home/smartev/.node-red';
}

const DATA_DIR = resolveDataDir();
const SMART_FILE = path.join(DATA_DIR, 'smart-parking-config.json');
const CARS_FILE = path.join(DATA_DIR, 'cars-config.json');
const STATES_FILE = path.join(DATA_DIR, 'last-ui-states.json');

function readJsonFile(fp) {
    try {
        if (!fs.existsSync(fp)) return null;
        const raw = fs.readFileSync(fp, 'utf8');
        if (!raw || !raw.trim()) return null;
        return JSON.parse(raw);
    } catch (e) { node.warn('read ' + fp + ': ' + e.message); return null; }
}

function writeJsonFile(fp, obj) {
    try {
        const tmp = fp + '.tmp';
        fs.writeFileSync(tmp, JSON.stringify(obj, null, 2), 'utf8');
        fs.renameSync(tmp, fp);
        return true;
    } catch (e) { node.error('write ' + fp + ': ' + e.message); return false; }
}

function normalizeSmart(cfg) {
    if (!cfg || typeof cfg !== 'object') return null;
    return {
        FLOORS: Array.isArray(cfg.FLOORS) ? cfg.FLOORS : [],
        CHARGERS: (cfg.CHARGERS && typeof cfg.CHARGERS === 'object') ? cfg.CHARGERS : {},
        USERS: (cfg.USERS && typeof cfg.USERS === 'object') ? cfg.USERS : {},
        TOTAL_POWER: (cfg.TOTAL_POWER !== undefined && cfg.TOTAL_POWER !== null) ? Number(cfg.TOTAL_POWER) : (cfg.maxPower !== undefined && cfg.maxPower !== null ? Number(cfg.maxPower) : undefined),
        maxPower: (cfg.maxPower !== undefined && cfg.maxPower !== null) ? Number(cfg.maxPower) : (cfg.TOTAL_POWER !== undefined && cfg.TOTAL_POWER !== null ? Number(cfg.TOTAL_POWER) : undefined)
    };
}

function hasData(cfg) {
    if (!cfg) return false;
    return Object.keys(cfg.USERS || {}).length > 0
        || Object.keys(cfg.CHARGERS || {}).length > 0
        || (cfg.FLOORS && cfg.FLOORS.length > 0);
}

let _cfg = loadSmartConfig();
global.set('TOTAL_POWER', _cfg.TOTAL_POWER || _cfg.maxPower || 35);

if (msg.payload && msg.payload.type === 'set_global_limit') {
    let limit = Number(msg.payload.limit);
    if (!isNaN(limit) && limit >= 6) {
        global.set('TOTAL_POWER', limit);
        let currentCfg = loadSmartConfig();
        currentCfg.TOTAL_POWER = limit;
        currentCfg.maxPower = limit;
        saveSmartConfig(currentCfg);
        node.warn('✅ Global Power Limit set to ' + limit + ' kW via UI');

        msg.payload = { type: 'global_limit_update', limit: limit };
        return [msg, null, null];
    }
}

function loadSmartConfig() {
    const fromMem = global.get('smartParkingConfig');
    if (hasData(fromMem)) return fromMem;
    const fromFile = normalizeSmart(readJsonFile(SMART_FILE));
    if (hasData(fromFile)) {
        global.set('smartParkingConfig', fromFile);
        return fromFile;
    }
    const cfg = normalizeSmart(SEED_CONFIG);
    global.set('smartParkingConfig', cfg);
    return cfg;
}

function saveSmartConfig(cfg) {
    let n = normalizeSmart(cfg);
    if (!hasData(n)) { node.warn('Save rejected: empty'); return loadSmartConfig(); }

    if (!n.FLOORS.length) {
        const old = loadSmartConfig();
        if (old && old.FLOORS.length) n.FLOORS = old.FLOORS;
    }

    global.set('smartParkingConfig', n);
    if (n.maxPower !== undefined && n.maxPower !== null) {
        global.set('TOTAL_POWER', Number(n.maxPower));
    } else if (n.TOTAL_POWER !== undefined && n.TOTAL_POWER !== null) {
        global.set('TOTAL_POWER', Number(n.TOTAL_POWER));
    }

    fs.promises.writeFile(SMART_FILE + '.tmp', JSON.stringify(n, null, 2), 'utf8')
        .then(() => fs.promises.rename(SMART_FILE + '.tmp', SMART_FILE))
        .then(() => {
            const count = Object.keys(n.USERS).length;
            node.status({ fill: 'blue', shape: 'dot', text: 'Saved ' + count + ' users → ' + SMART_FILE });
        })
        .catch(err => {
            node.status({ fill: 'red', shape: 'dot', text: 'WRITE FAILED' });
            node.error('Cannot write config: ' + err.message);
        });

    return n;
}

function loadCarsConfig() {
    const fromMem = global.get('carsConfig');
    if (fromMem && Object.keys(fromMem).length > 0) return fromMem;
    const fromFile = readJsonFile(CARS_FILE);
    const cfg = fromFile || {};
    global.set('carsConfig', cfg);
    return cfg;
}

function saveCarsConfig(cfg) {
    if (!cfg || typeof cfg !== 'object') cfg = {};
    global.set('carsConfig', cfg);
    fs.promises.writeFile(CARS_FILE + '.tmp', JSON.stringify(cfg, null, 2), 'utf8')
        .then(() => fs.promises.rename(CARS_FILE + '.tmp', CARS_FILE))
        .catch(err => node.error('Write cars config failed: ' + err.message));
    return cfg;
}

function loadLastUiStates() {
    const fromMem = flow.get('last_ui_states');
    if (fromMem && Object.keys(fromMem).length > 0) return fromMem;
    const fromFile = readJsonFile(STATES_FILE);
    const states = fromFile || {};
    flow.set('last_ui_states', states);
    return states;
}

function saveLastUiStates(states) {
    if (!states || typeof states !== 'object') states = {};
    flow.set('last_ui_states', states);
    fs.promises.writeFile(STATES_FILE + '.tmp', JSON.stringify(states, null, 2), 'utf8')
        .then(() => fs.promises.rename(STATES_FILE + '.tmp', STATES_FILE))
        .catch(err => node.error('Write last ui states failed: ' + err.message));
    return states;
}

if (!msg || !msg.topic) return [null, null];

if (msg.topic === 'get_charging_history') {
    try {
        const histFile = path.join(DATA_DIR, 'charging-history.json');
        let history = [];
        if (fs.existsSync(histFile)) {
            const raw = fs.readFileSync(histFile, 'utf8');
            if (raw && raw.trim()) {
                history = JSON.parse(raw);
            }
        }
        msg.payload = { type: 'charging_history_response', history: history };
        return [msg, null, null, null];
    } catch(e) {
        msg.payload = { type: 'charging_history_response', history: [] };
        return [msg, null, null, null];
    }
}
const topic = msg.topic;

if (topic === 'factory_reset_config') {
    const cfg = normalizeSmart(SEED_CONFIG);
    writeJsonFile(SMART_FILE, cfg);
    global.set('smartParkingConfig', cfg);
    writeJsonFile(STATES_FILE, {});
    flow.set('last_ui_states', {});
    node.status({ fill: 'red', shape: 'dot', text: 'Factory reset' });
    return [{ payload: { type: 'smart_config', config: cfg } }, null];
}

if (topic === 'restore_seed_config') {
    const cfg = normalizeSmart(SEED_CONFIG);
    writeJsonFile(SMART_FILE, cfg);
    global.set('smartParkingConfig', cfg);
    node.status({ fill: 'green', shape: 'dot', text: 'Seed restored' });
    return [{ payload: { type: 'smart_config', config: cfg } }, null];
}

if (topic === 'reload_from_disk') {
    const cfg = loadSmartConfig();
    loadLastUiStates();
    node.status({ fill: 'green', shape: 'ring', text: 'Reloaded config & states' });
    return [{ payload: { type: 'smart_config', config: cfg } }, null];
}

if (topic === '__preload_config__') {
    loadSmartConfig();
    loadCarsConfig();
    loadLastUiStates();
    node.status({ fill: 'green', shape: 'ring', text: 'Loaded: ' + SMART_FILE });
    return [null, null];
}

if (topic === 'smart_config_request') {

    node.send([{ payload: { type: 'smart_config', config: loadSmartConfig() } }, null]);

    const states = loadLastUiStates();
    for (let key in states) {
        node.send([{ payload: states[key] }, null]);
    }

    return [null, null];
}

if (topic === 'save_smart_config') {
    const saved = saveSmartConfig(msg.payload);
    return [{ payload: { type: 'smart_config', config: saved } }, null];
}

if (topic === 'save_car_ui') {
    const cars = loadCarsConfig();
    cars[msg.payload.zoneId + '-' + msg.payload.spot] = { name: msg.payload.name, color: msg.payload.color };
    return [{ payload: { type: 'cars_config', config: saveCarsConfig(cars) } }, null];
}

if (topic === 'cars_config_request') {
    return [{ payload: { type: 'cars_config', config: loadCarsConfig() } }, null];
}

if (topic === 'rfid_history_request' || topic === 'rfid_history_clear' || topic === 'rfid_notifications_read') {
    return [null, msg];
}

if (topic === 'heartbeat') {
    msg.payload = { type: 'heartbeat_ack', ts: msg.payload ? msg.payload.ts : Date.now() };
    return [msg, null, null, null];
}

if (topic === 'system_reboot') {
    node.status({ fill: 'red', shape: 'dot', text: 'Rebooting system...' });
    child_process.exec('sudo reboot', function(err) {
        if(err) node.error('Reboot failed: ' + String(err));
    });
    return [null, null];
}

if (topic === 'rfid_multi_choice') {
    return [null, null, null, msg];
}
if (topic === 'set_charger_amp') {
    const smartConf = loadSmartConfig();
    let chargerId = null;
    let chargerType = null;
    let conf = null;
    if (smartConf && smartConf.CHARGERS) {
        for (let cid in smartConf.CHARGERS) {
            const c = smartConf.CHARGERS[cid];
            if (c.zone === msg.payload.zoneId && String(c.spot) === String(msg.payload.spot)) {
                chargerId = cid;
                chargerType = c.type || cid.split('_')[0];
                conf = c;
                break;
            }
        }
    }
    if (chargerId) {

        let states = flow.get('last_ui_states') || loadLastUiStates() || {};
        if (!states[chargerId]) {
            states[chargerId] = { zoneId: msg.payload.zoneId, spot: msg.payload.spot, occupied: false, power: 0 };
        }

        const type = chargerType || (chargerId.includes('victron') ? 'victron' : (chargerId.includes('easee') ? 'easee' : 'goe'));
        const defaultMinAmp = (type === 'victron') ? 16 : 6;
        const defaultMaxAmp = (type === 'victron') ? 20 : 32;

        const minAmp = (conf && conf.minAmp !== undefined && conf.minAmp !== null) ? Number(conf.minAmp) : defaultMinAmp;
        const maxAmp = (conf && conf.maxAmp !== undefined && conf.maxAmp !== null) ? Number(conf.maxAmp)
                      : ((conf && conf.amp !== undefined && conf.amp !== null) ? Number(conf.amp) : defaultMaxAmp);

        let inputAmp = Number(msg.payload.amp);
        if (isNaN(inputAmp) || inputAmp < minAmp) {
            inputAmp = minAmp;
        } else if (inputAmp > maxAmp) {
            inputAmp = maxAmp;
        }

        states[chargerId].amp = inputAmp;
        states[chargerId].targetAmp = inputAmp;
        states[chargerId].desiredAmp = inputAmp;
        saveLastUiStates(states);

        msg.chargerId = chargerId;
        msg.chargerType = chargerType;
        return [null, null, msg];
    }
    return [null, null, null];
}
return [null, null];

