// Load config and states immediately on startup to avoid timing races
try {
    function resolveDataDir() {
        const candidates = [
            '/home/smartev/.node-red',
            '/home/pi/.node-red',
            '/root/.node-red',
            '/data'
        ];
        if (typeof RED !== 'undefined' && RED.settings && RED.settings.userDir) {
            candidates.unshift(RED.settings.userDir);
        }
        for (let i = 0; i < candidates.length; i++) {
            if (fs.existsSync(candidates[i])) { return candidates[i]; }
        }
        return '/home/smartev/.node-red';
    }

    const DATA_DIR = resolveDataDir();
    const STATES_FILE = path.join(DATA_DIR, 'last-ui-states.json');

    if (fs.existsSync(STATES_FILE)) {
        const raw = fs.readFileSync(STATES_FILE, 'utf8');
        if (raw && raw.trim()) {
            const states = JSON.parse(raw) || {};
            flow.set('last_ui_states', states);

            let validUserNames = [];
            try {
                const SMART_FILE = path.join(DATA_DIR, 'smart-parking-config.json');
                if (fs.existsSync(SMART_FILE)) {
                    const cfg = JSON.parse(fs.readFileSync(SMART_FILE, 'utf8'));
                    if (cfg && cfg.USERS) {
                        validUserNames = Object.values(cfg.USERS).map(u => u.name);
                    }
                }
            } catch(e) {}

            // Restore individual charger parser states
            for (let cid in states) {
                const cached = states[cid];
                const rawStatus = cached.raw_status !== undefined ? cached.raw_status : (cached.occupied ? 2 : 0);
                let user = cached.activeUser || '';
                const card = cached.activeCard || '';

                if (user && !validUserNames.includes(user)) {
                    user = '';
                }

                if (cid.startsWith('victron')) {
                    flow.set('victron_status_' + cid, rawStatus);
                    flow.set('victron_notif_status_' + cid, rawStatus);
                    flow.set('victron_current_user_' + cid, user);
                    flow.set('victron_current_card_' + cid, card);
                    flow.set('victron_is_offline_' + cid, cached.isOffline || false);
                } else if (cid.startsWith('goe')) {
                    flow.set('goe_status_' + cid, rawStatus);
                    flow.set('goe_notif_status_' + cid, rawStatus);
                    flow.set('goe_current_user_' + cid, user);
                    flow.set('goe_current_card_' + cid, card);
                    flow.set('goe_is_offline_' + cid, cached.isOffline || false);
                } else if (cid.startsWith('easee')) {
                    flow.set('easee_op_mode_' + cid, rawStatus);
                    flow.set('easee_current_user_' + cid, user);
                    flow.set('easee_current_card_' + cid, card);
                    flow.set('easee_is_offline_' + cid, cached.isOffline || false);
                }
            }
        }
    }
} catch(e) {
    node.error('Startup states restoration failed: ' + e.message);
}

