if (msg.statusCode !== 200) {
    node.error('Login failed: ' + msg.statusCode);
    msg.payload = { occupied: false, power: 0, name: 'Login Error', zoneId: '1A', spot: 1 };
    return [null, msg];
}
try {
    var data = JSON.parse(msg.payload);
    flow.set('easee_token', data.accessToken);
    msg.headers = {
        'Authorization': 'Bearer ' + data.accessToken,
        'Accept': 'application/json'
    };
    msg.payload = {};
    return [msg, null];
} catch(e) {
    node.error('Login parse error: ' + e.message);
    msg.payload = { occupied: false, power: 0, name: 'Parse Error', zoneId: '1A', spot: 1 };
    return [null, msg];
}

if (msg.statusCode !== 200) {
    node.error('Chargers failed: ' + msg.statusCode);
    msg.payload = { occupied: false, power: 0, name: 'Charger Error', zoneId: '1A', spot: 1 };
    return [null, msg];
}
try {
    var chargers = JSON.parse(msg.payload);
    var id = chargers[0].id;
    flow.set('easee_charger', id);
    var token = flow.get('easee_token');
    msg.url = 'https://api.easee.com/api/chargers/' + id + '/state';
    msg.headers = {
        'Authorization': 'Bearer ' + token,
        'Accept': 'application/json'
    };
    msg.payload = {};
    return [msg, null];
} catch(e) {
    node.error('Charger parse error: ' + e.message);
    msg.payload = { occupied: false, power: 0, name: 'Parse Error', zoneId: '1A', spot: 1 };
    return [null, msg];
}

var token = flow.get('easee_token');
var chargerId = flow.get('easee_charger');
if (!token || !chargerId) {

    flow.set('easee_token', null);
    node.error('No token or charger cached, re-login needed');
    return null;
}
msg.url = 'https://api.easee.com/api/chargers/' + chargerId + '/state';
msg.headers = {
    'Authorization': 'Bearer ' + token,
    'Accept': 'application/json'
};
msg.payload = {};
return msg;

const cid = msg.chargerId;

const conf = (global.get('smartParkingConfig', 'default') || global.get('smartParkingConfig')) || { CHARGERS: {} };
const chConf = (conf.CHARGERS && conf.CHARGERS[cid]) ? conf.CHARGERS[cid] : { zone: '1B', spot: 1 };

let isOffline = flow.get('easee_is_offline_' + cid) || false;

if (msg.statusCode === 401 || msg.statusCode !== 200) {
    if (msg.statusCode === 401) {
        flow.set('easee_token', null);
        flow.set('easee_charger', null);
    }

    let dcTime = flow.get('easee_dc_time_' + cid) || 0;
    if (!dcTime) {
        flow.set('easee_dc_time_' + cid, Date.now());
        return null;
    } else if (Date.now() - dcTime <= 10000) {
        return null;
    } else {
        if (isOffline) return null;
        flow.set('easee_is_offline_' + cid, true);
        // flow.set('easee_current_user_' + cid, '');
        msg.payload = { occupied: false, power: 0, name: 'Offline / API Error', zoneId: chConf.zone, spot: chConf.spot, isOffline: true };

        return [msg, null, null];
    }
}

try {
    var easee = JSON.parse(msg.payload);
    var opMode = Number(easee.chargerOpMode);
    var power  = Number(easee.totalPower) || 0;

    let physicallyOccupied = (opMode === 2 || opMode === 3 || opMode === 4);
    let dcTime = flow.get('easee_dc_time_' + cid) || 0;

    flow.set('easee_dc_time_' + cid, 0);
    flow.set('easee_is_offline_' + cid, false);
    if (!physicallyOccupied) {
        flow.set('easee_current_user_' + cid, '');
        flow.set('easee_current_card_' + cid, '');
        /* REMOVED: flow.set('easee_auth_pending_time_' + cid, 0); */
    }

    let occupied = physicallyOccupied;

    let sessionEnergy = 0;
    if (occupied) {
        let lastTs = flow.get('easee_energy_ts_' + cid);
        let curEnergy = flow.get('easee_session_energy_' + cid) || 0;
        let nowTs = Date.now();
        if (lastTs && lastTs > 0) {
            let dtHours = (nowTs - lastTs) / 3600000.0;
            curEnergy += power * dtHours;
        }
        flow.set('easee_energy_ts_' + cid, nowTs);
        flow.set('easee_session_energy_' + cid, curEnergy);
        sessionEnergy = curEnergy;
    } else {
        flow.set('easee_energy_ts_' + cid, 0);
        flow.set('easee_session_energy_' + cid, 0);
    }

    const prevOpMode = flow.get('easee_op_mode_' + cid) || 0;
    flow.set('easee_op_mode_' + cid, opMode);

    var currentUser = flow.get('easee_current_user_' + cid) || '';
    var currentCard = flow.get('easee_current_card_' + cid) || '';
    var notifUser = currentUser + (currentCard ? ' (' + currentCard + ')' : '');

    let autoStartMsg = null;
    let notificationToast = null;

    if (opMode === 2) {
        const pTime = flow.get('easee_auth_pending_time_' + cid) || 0;
        const pUser = flow.get('easee_auth_pending_user_' + cid) || '';
        const pCard = flow.get('easee_auth_pending_card_' + cid) || '';
        if (pUser && (Date.now() - pTime < 60000)) {
            flow.set('easee_auth_pending_time_' + cid, 0);
            flow.set('easee_auth_pending_user_' + cid, '');
            flow.set('easee_current_user_' + cid, pUser);
            flow.set('easee_current_card_' + cid, pCard);
            currentUser = pUser;
            autoStartMsg = { payload: { authorized: true, charger: cid, name: pUser, card_id: pCard } };
            notificationToast = { payload: { text: `Easee (${cid}): Vehicle connected. Starting...`, user: pUser } };
        }
    }

    if (prevOpMode !== 3 && opMode === 3) {
        notificationToast = { payload: { type: 'rfid_notification', text: `Easee (${cid}): Charging started.`, user: notifUser } };
    } else if (prevOpMode === 3 && opMode !== 3) {
        notificationToast = { payload: { type: 'rfid_notification', text: `Easee (${cid}): Charging stopped.`, user: notifUser } };
    }

    var modeNames = { 1: '', 2: 'Easee EV (Ready)', 3: 'Easee EV', 4: 'Completed', 5: 'Easee Error', 6: 'Easee Offline' };
    var defaultName = occupied ? (currentUser || modeNames[opMode] || 'Easee EV') : '';

    var carsConfig = global.get('carsConfig', 'default');
    var cConf = (carsConfig && carsConfig[chConf.zone + '-' + chConf.spot]) ? carsConfig[chConf.zone + '-' + chConf.spot] : {};
    var name = cConf.name ? cConf.name : defaultName;
    var color = cConf.color ? cConf.color : null;

    msg.payload = { occupied: occupied, power: power, name: name, color: color, isCharged: (opMode === 3 && power === 0) || (opMode === 4), sessionEnergy: sessionEnergy, zoneId: chConf.zone, spot: chConf.spot, isOffline: false, activeCard: currentCard, activeUser: currentUser };

    node.status({ fill: occupied ? 'green' : 'grey', shape: 'dot', text: 'opMode:' + opMode + ' ' + power.toFixed(2) + 'kW' });
    return [msg, autoStartMsg, notificationToast];

} catch(e) {
    node.warn('Easee Parse Exception: ' + e.message);
    let dcTime = flow.get('easee_dc_time_' + cid) || 0;
    if (!dcTime) {
        flow.set('easee_dc_time_' + cid, Date.now());
        return null;
    } else if (Date.now() - dcTime > 10000) {
        if (isOffline) return null;
        flow.set('easee_is_offline_' + cid, true);
        msg.payload = { occupied: false, power: 0, name: 'Parse Error', zoneId: chConf.zone, spot: chConf.spot, isOffline: true };

        return [msg, null, null];
    }
    return null;
}

let cid = msg.chargerId;

const smartConf = (global.get('smartParkingConfig', 'default') || global.get('smartParkingConfig')) || {CHARGERS:{}};
let conf = smartConf.CHARGERS[cid];
if (!conf && cid) {
    if (smartConf.CHARGERS[cid + '_1']) {
        conf = smartConf.CHARGERS[cid + '_1'];
        cid = cid + '_1';
        msg.chargerId = cid;
    } else if (cid.endsWith('_1') && smartConf.CHARGERS[cid.slice(0, -2)]) {
        conf = smartConf.CHARGERS[cid.slice(0, -2)];
        cid = cid.slice(0, -2);
        msg.chargerId = cid;
    }
}
if (!conf) return msg;

let currentAmp = msg.amp !== undefined ? msg.amp : (conf ? conf.amp : 16);
const statesCache = flow.get('last_ui_states') || {};
const oldState = statesCache[cid] || {};
const ampChanged = (oldState.amp !== undefined && Number(oldState.amp) !== Number(currentAmp));

if (msg.info && typeof msg.info === 'string' && msg.info.toLowerCase().includes('error')) {
    let dcTime = flow.get('victron_dc_time_' + cid) || 0;
    let isOffline = flow.get('victron_is_offline_' + cid) || false;

    if (!dcTime) {
        flow.set('victron_dc_time_' + cid, Date.now());
        return null;
    } else if (Date.now() - dcTime <= 10000) {
        return null;
    } else {
        if (isOffline) {
            return null;
        } else {
            flow.set('victron_is_offline_' + cid, true);
            // flow.set('victron_current_user_' + cid, '');
            flow.set('victron_active_command_' + cid, 0);

            msg.payload = { occupied: false, power: 0, name: 'Offline / Modbus Error', zoneId: conf.zone, spot: conf.spot, isOffline: true };
            return [msg, null, null];
        }
    }
}

const r = msg.payload;
if (!r || !Array.isArray(r) || r.length < 7) return null;

const chargeMode  = r[0] || 0;
const startStop   = r[1] || 0;
const powerL1     = r[2] || 0;
const powerL2     = r[3] || 0;
const powerL3     = r[4] || 0;
let rawTotalW     = r[5] || 0;
let rawStatus     = r[6] || 0;

let rawTotalKW = rawTotalW / 1000.0;
const energyKWh = flow.get('victron_energy_kwh_' + cid) || 0;


let currentName = flow.get('victron_current_user_' + cid) || 'Charging...';
let currentCard = flow.get('victron_current_card_' + cid) || '';
let physicallyOccupied = (rawStatus >= 1 && rawStatus !== 0);

let dcTime = flow.get('victron_dc_time_' + cid) || 0;
let isOffline = flow.get('victron_is_offline_' + cid) || false;

    flow.set('victron_dc_time_' + cid, 0);
    flow.set('victron_is_offline_' + cid, false);
    if (!physicallyOccupied) {
        flow.set('victron_current_user_' + cid, '');
        flow.set('victron_current_card_' + cid, '');
        flow.set('victron_active_command_' + cid, 0);

        currentName = '';
    }

let occupied = physicallyOccupied;

// Diagnostic snapshot (throttled) for register mapping verification
const lastDiagTs = flow.get('victron_diag_ts_' + cid) || 0;
const nowDiagTs = Date.now();
if (nowDiagTs - lastDiagTs > 10000) {
    flow.set('victron_diag_ts_' + cid, nowDiagTs);
    const sumPhaseW = (powerL1 || 0) + (powerL2 || 0) + (powerL3 || 0);
    // node.warn('[VIC-DIAG] cid=' + cid +
        // ' regs=' + JSON.stringify({ r0: chargeMode, r1: startStop, r2: powerL1, r3: powerL2, r4: powerL3, r5: rawTotalW, r6: rawStatus }) +
        // ' totalKW=' + rawTotalKW.toFixed(2) +
        // ' sumPhaseW=' + sumPhaseW +
        // ' ampRead=' + currentAmp +
        // ' occupied=' + occupied +
        // ' status=' + rawStatus);
}

let sessionEnergy = 0;
if (occupied) {
    let initialEnergy = flow.get('victron_initial_energy_' + cid);
    if (initialEnergy === undefined || initialEnergy === null || initialEnergy === 0) {
        flow.set('victron_initial_energy_' + cid, energyKWh);
        initialEnergy = energyKWh;
    }
    sessionEnergy = Math.max(0, energyKWh - initialEnergy);
} else {
    flow.set('victron_initial_energy_' + cid, 0);
}

const prevNotifStatus = flow.get('victron_notif_status_' + cid) || 0;
flow.set('victron_notif_status_' + cid, rawStatus);
flow.set('victron_status_' + cid, rawStatus);

let autoStartMsg = null;
let notificationToast = null;

if (occupied && (rawStatus === 1 || rawStatus === 5 || rawStatus === 6)) {
    const pendingTime = flow.get('victron_auth_pending_time_' + cid) || 0;
    const pendingUser = flow.get('victron_auth_pending_user_' + cid) || '';
    const pendingCard = flow.get('victron_auth_pending_card_' + cid) || '';
    if (pendingUser && (Date.now() - pendingTime < 60000)) {
        flow.set('victron_auth_pending_time_' + cid, 0);
        flow.set('victron_auth_pending_user_' + cid, '');
        flow.set('victron_active_command_' + cid, 1);
        flow.set('victron_current_user_' + cid, pendingUser);
        flow.set('victron_current_card_' + cid, pendingCard);
        flow.set('victron_current_card_' + cid, pendingCard);
        flow.set('pending_rfid_command_' + cid, 1);
        flow.set('pending_rfid_user_' + cid, pendingUser);
        autoStartMsg = { payload: { authorized: true, charger: cid, name: pendingUser, command: 1, card_id: pendingCard, fc: 6, unitid: 1, address: 5009, value: 0, quantity: 1 } };
        notificationToast = { payload: { type: 'rfid_notification', text: 'Victron: Vehicle connected. Starting charge...', user: pendingUser + (pendingCard ? ' (' + pendingCard + ')' : '') } };
        currentName = pendingUser;
    }
}

if (prevNotifStatus !== 2 && rawStatus === 2) {
    notificationToast = { payload: { type: 'rfid_notification', text: 'Victron: Charging started.', user: currentName } };
} else if (prevNotifStatus === 2 && rawStatus !== 2) {
    notificationToast = { payload: { type: 'rfid_notification', text: 'Victron: Charging stopped.', user: currentName } };
}



const statusLabels = { 0: 'Disconnected', 1: 'Connected', 2: 'Charging', 3: 'Completed', 4: 'Waiting for Sun', 5: 'Waiting for RFID', 6: 'Waiting to Start', 7: 'Low SOC', 20: 'Charge Limit', 21: 'Starting Charge', 24: 'Stopping Charge' };
const carsConfig = global.get('carsConfig', 'default') || {};

const cConf = carsConfig[(conf ? conf.zone : '1B') + '-' + (conf ? conf.spot : 1)] || {};
const finalName  = cConf.name ? cConf.name : (currentName || statusLabels[rawStatus] || 'Status ' + rawStatus);
const finalColor = cConf.color ? cConf.color : '#f5a623';

msg.payload = { occupied: occupied, power: rawTotalKW, powerW: rawTotalW, powerL1: powerL1, powerL2: powerL2, powerL3: powerL3, energy: energyKWh, sessionEnergy: sessionEnergy, amp: currentAmp, name: finalName, color: finalColor, zoneId: (conf ? conf.zone : '1B'), spot: (conf ? conf.spot : 1), raw_status: rawStatus, status_label: statusLabels[rawStatus] || 'Status ' + rawStatus, charge_mode: chargeMode, isCharged: (rawStatus === 3), isOffline: false, activeCard: currentCard, activeUser: currentName };

return [msg, autoStartMsg, notificationToast];

if (!msg.payload || !Array.isArray(msg.payload) || msg.payload.length < 1) {
    return null;
}
const raw = msg.payload[0] || 0;
const kwh = raw / 100.0;
const cid = msg.chargerId;

flow.set('victron_energy_kwh_' + cid, kwh);

node.status({ fill: 'green', shape: 'dot', text: cid + ' Energy: ' + kwh.toFixed(2) + ' kWh' });
return null;

function normalizeCardId(value) {
    if (value === undefined || value === null) return '';
    return String(value).trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
}

const payload = (msg && msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const rawCardId = payload.card_id || payload.cardId || payload.uid || payload.rfid || msg.card_id || msg.cardId;
const cardId = normalizeCardId(rawCardId);

if (cardId) {
    node.send([null, null, null, { topic: 'last_scanned_card', payload: { card_id: cardId } }]);
}

if (!cardId) {
    return [null, null, null, null];
}

const smartConf = (global.get('smartParkingConfig', 'default') || global.get('smartParkingConfig')) || { USERS: {} };
const USERS = smartConf.USERS;

const user = USERS[cardId];
if (!user) {
    node.warn('Unknown Card: ' + cardId);
    return [null, null, null, null];
}

const { name: userName, charger: allowedChargerStr, isAdmin } = user;

let allowedChargersList = [allowedChargerStr];
if (typeof allowedChargerStr === 'string' && allowedChargerStr.indexOf(',') !== -1) {
    allowedChargersList = allowedChargerStr.split(',').map(s => s.trim());
} else if (Array.isArray(allowedChargerStr)) {
    allowedChargersList = allowedChargerStr;
}

let smartConfInner = (global.get('smartParkingConfig', 'default') || global.get('smartParkingConfig')) || { CHARGERS: {} };
allowedChargersList = allowedChargersList.map(cid => {
    if (smartConfInner.CHARGERS && smartConfInner.CHARGERS[cid]) return cid;
    if (smartConfInner.CHARGERS) {
        for (let realId in smartConfInner.CHARGERS) {
            if (realId === cid || realId.split('_')[0] === cid.split('_')[0]) {
                return realId;
            }
        }
    }
    return cid;
});

if (!payload.is_choice && allowedChargersList.length > 1) {
    let smartConfInner = (global.get('smartParkingConfig', 'default') || global.get('smartParkingConfig')) || { CHARGERS: {} };
    let chargerStatuses = allowedChargersList.map(cid => {
        let type = (smartConfInner.CHARGERS && smartConfInner.CHARGERS[cid]) ? smartConfInner.CHARGERS[cid].type : cid.split('_')[0];
        let statusStr = "Available";
        let isCharging = false;
        let pwr = 0;
        const states = flow.get('last_ui_states') || {};
        const chState = states[cid] || {};
        pwr = chState.power || 0;

        if (type === 'victron') {
            let vStat = Number(flow.get('victron_status_' + cid) || 0);
            isCharging = (vStat === 2 || vStat === 21);
            statusStr = isCharging ? "Charging" : (vStat >= 1 ? "Connected" : "Available");
        } else if (type === 'easee') {
            let eStat = Number(flow.get('easee_op_mode_' + cid) || 0);
            isCharging = (eStat === 3);
            statusStr = isCharging ? "Charging" : ((eStat===2||eStat===3) ? "Connected" : "Available");
        } else if (type === 'goe' || type === 'go-e') {
            let gStat = Number(flow.get('goe_status_' + cid) || 0);
            let allowGoe = flow.get('goe_allow_charging_' + cid) !== undefined ? Number(flow.get('goe_allow_charging_' + cid)) : 0;
            isCharging = (gStat === 2 || gStat === 4) && (allowGoe === 0);
            statusStr = isCharging ? "Charging" : ((gStat>=2 && gStat<=4) ? "Connected" : "Available");
        }
        return { id: cid, type: type, status: statusStr, isCharging: isCharging, power: pwr };
    });

    // Write ACK so the reader beeps green (success) for multi-charger choice
    const ackDir = '/dev/shm/rfid_ack';
    const ackFile = ackDir + '/ack_' + cardId;
    try {
        if (!fs.existsSync(ackDir)) fs.mkdirSync(ackDir, { recursive: true });
        fs.writeFileSync(ackFile, 'ok');
        node.warn('✅ RFID ACK written for multi-charger choice: ' + cardId);
    } catch(e) {
        node.error('Failed to write RFID ACK: ' + e.message);
    }

    return [null, null, null, { topic: 'rfid_multi_charger', payload: { type: 'rfid_multi_charger', topic: 'rfid_multi_charger', card_id: cardId, user: userName, chargers: chargerStatuses } }];
}

let activeCharger = payload.is_choice ? payload.charger_choice : allowedChargersList[0];
let switchFrom = payload.switch_from || null;

let victronMsgs = [];
let easeeMsgs = [];
let goeMsgs = [];
let toast = '';

// Helper function to build a command message for a specific charger
function queueCommand(cid, cmd, isSwitchStop = false) {
    const cConf = (smartConf.CHARGERS && cid) ? smartConf.CHARGERS[cid] : null;
    const cType = (cConf && cConf.type) ? cConf.type : (cid || '').split('_')[0];

    if (cmd === 1) {
        let states = flow.get('last_ui_states') || {};
        let defaultAmp = 16;
        if (smartConf.CHARGERS && smartConf.CHARGERS[cid] && smartConf.CHARGERS[cid].amp) {
            defaultAmp = Number(smartConf.CHARGERS[cid].amp) || 16;
        }
        if (!states[cid]) {
            states[cid] = {
                zoneId: cConf ? cConf.zone : '',
                spot: cConf ? cConf.spot : '',
                occupied: true,
                power: 0
            };
        }
        states[cid].amp = defaultAmp;
        states[cid].targetAmp = defaultAmp;
        states[cid].desiredAmp = defaultAmp;
        flow.set('last_ui_states', states);
    }

    if (cType === 'victron') {
        const victronStatus = Number(flow.get('victron_status_' + cid) || 0);
        const isCableConnected = (victronStatus >= 1);

        if (!isCableConnected && cmd === 1) {
            flow.set('victron_auth_pending_user_' + cid, userName);
            flow.set('victron_auth_pending_time_' + cid, Date.now());
            flow.set('victron_auth_pending_card_' + cid, cardId);
            if (!isSwitchStop) {
                toast = `Victron (${cid}): Auth successful. Connect vehicle within 60s.`;
            }
        } else {
            flow.set('victron_auth_pending_time_' + cid, 0);
            flow.set('victron_active_command_' + cid, cmd);
            if (cmd === 1) {
                flow.set('victron_current_user_' + cid, userName);
                flow.set('victron_current_card_' + cid, cardId);
                if (!isSwitchStop) toast = `Victron (${cid}): Preparing to start...`;
            } else {
                flow.set('victron_current_user_' + cid, '');
                flow.set('victron_current_card_' + cid, '');
                if (!isSwitchStop) toast = `Victron (${cid}): Preparing to stop...`;
            }
            flow.set('pending_rfid_command_' + cid, cmd);
            flow.set('pending_rfid_user_' + cid, userName);

            let outMsg = Object.assign({}, msg, {
                payload: Object.assign({}, payload, {
                    card_id: cardId,
                    name: userName,
                    authorized: true,
                    charger: cid,
                    command: cmd
                }),
                chargerId: cid
            });
            victronMsgs.push(outMsg);
        }
    } else if (cType === 'easee') {
        const easeeOpMode = Number(flow.get('easee_op_mode_' + cid) || 0);
        const easeeCableConnected = (easeeOpMode === 2 || easeeOpMode === 3);

        if (!easeeCableConnected && cmd === 1) {
            flow.set('easee_auth_pending_user_' + cid, userName);
            flow.set('easee_auth_pending_time_' + cid, Date.now());
            flow.set('easee_auth_pending_card_' + cid, cardId);
            if (!isSwitchStop) toast = `Easee (${cid}): Auth successful. Connect vehicle within 60s.`;
        } else {
            flow.set('easee_auth_pending_time_' + cid, 0);
            flow.set('easee_current_user_' + cid, cmd === 1 ? userName : '');
            flow.set('easee_current_card_' + cid, cmd === 1 ? cardId : '');

            let outMsg = {
                payload: {
                    card_id: cardId,
                    name: userName,
                    authorized: true,
                    charger: cid
                },
                chargerId: cid
            };
            easeeMsgs.push(outMsg);
            if (!isSwitchStop) {
                toast = cmd === 1 ? `Easee (${cid}): Preparing to start...` : `Easee (${cid}): Preparing to stop...`;
            }
        }
    } else if (cType === 'goe' || cType === 'go-e') {
        const rawGoe = Number(flow.get('goe_status_' + cid) || 0);
        const goeCableConnected = (rawGoe >= 2 && rawGoe <= 4);

        if (!goeCableConnected && cmd === 1) {
            flow.set('goe_auth_pending_user_' + cid, userName);
            flow.set('goe_auth_pending_time_' + cid, Date.now());
            flow.set('goe_auth_pending_card_' + cid, cardId);
            if (!isSwitchStop) toast = `Go-E (${cid}): Auth successful. Connect vehicle within 60s.`;
        } else {
            flow.set('goe_auth_pending_time_' + cid, 0);
            flow.set('goe_current_user_' + cid, cmd === 1 ? userName : '');
            flow.set('goe_current_card_' + cid, cmd === 1 ? cardId : '');
            flow.set('goe_starting_session_' + cid, cmd === 1);

            let outMsg = {
                payload: {
                    fc: 16,
                    unitid: 1,
                    address: 201,
                    value: [cmd === 1 ? 0 : 1],
                    quantity: 1
                },
                chargerId: cid
            };
            goeMsgs.push(outMsg);
            if (!isSwitchStop) {
                toast = cmd === 1 ? `Go-E (${cid}): Preparing to start...` : `Go-E (${cid}): Preparing to stop...`;
            }
        }
    }
}

if (switchFrom) {
    // 1. Stop the switchFrom charger
    queueCommand(switchFrom, 0, true);

    // 2. Start the activeCharger
    queueCommand(activeCharger, 1, false);

    toast = `Switching charging from ${switchFrom} to ${activeCharger}...`;
} else {
    const cConf = (smartConf.CHARGERS && activeCharger) ? smartConf.CHARGERS[activeCharger] : null;
    const cType = (cConf && cConf.type) ? cConf.type : (activeCharger || '').split('_')[0];

    let isCharging = false;
    let currentUser = '';

    if (cType === 'victron') {
        const victronStatus = Number(flow.get('victron_status_' + activeCharger) || 0);
        isCharging = (victronStatus === 2 || victronStatus === 21);
        currentUser = flow.get('victron_current_user_' + activeCharger) || '';
    } else if (cType === 'easee') {
        const easeeOpMode = Number(flow.get('easee_op_mode_' + activeCharger) || 0);
        isCharging = (easeeOpMode === 3);
        currentUser = flow.get('easee_current_user_' + activeCharger) || '';
    } else if (cType === 'goe' || cType === 'go-e') {
        const rawGoe = Number(flow.get('goe_status_' + activeCharger) || 0);
        const allowGoe = flow.get('goe_allow_charging_' + activeCharger) !== undefined ? Number(flow.get('goe_allow_charging_' + activeCharger)) : 0;
        isCharging = (rawGoe === 2 || rawGoe === 4) && (allowGoe === 0);
        currentUser = flow.get('goe_current_user_' + activeCharger) || '';
    }

    let sessionUser = null;
    for (let uid in USERS) {
        if (USERS[uid].name === currentUser) {
            sessionUser = USERS[uid];
            break;
        }
    }
    if (currentUser && !sessionUser) {
        currentUser = '';
    }
    let isOwner = (currentUser === userName);
    let samePin = false;
    if (sessionUser && sessionUser.pin && user.pin && sessionUser.pin === user.pin) {
        samePin = true;
    }

    if (isCharging && currentUser && !isOwner && !samePin && !isAdmin) {
        node.warn(`RFID: Swipe by ${userName} ignored. Charger ${activeCharger} is locked by active session of ${currentUser}.`);
        const ackDir = '/dev/shm/rfid_ack';
        const ackFile = ackDir + '/ack_' + cardId;
        try {
            if (!fs.existsSync(ackDir)) fs.mkdirSync(ackDir, { recursive: true });
            fs.writeFileSync(ackFile, 'lock');
            node.warn('❌ RFID ACK written with lock status for card: ' + cardId);
        } catch(e) {
            node.error('Failed to write RFID ACK: ' + e.message);
        }
        let toastPayload = Object.assign({}, msg, {
            payload: {
                text: 'RFID Rejected: Charger is locked by ' + currentUser,
                user: userName,
                ts: Date.now()
            }
        });
        delete toastPayload.topic;
        return [null, null, null, toastPayload];
    }

    const cmd = isCharging ? 0 : 1;
    queueCommand(activeCharger, cmd, false);
}

let victronPayload = victronMsgs.length > 0 ? (victronMsgs.length === 1 ? victronMsgs[0] : victronMsgs) : null;
let easeePayload = easeeMsgs.length > 0 ? (easeeMsgs.length === 1 ? easeeMsgs[0] : easeeMsgs) : null;
let goePayload = goeMsgs.length > 0 ? (goeMsgs.length === 1 ? goeMsgs[0] : goeMsgs) : null;

let toastPayload = Object.assign({}, msg, { payload: { text: toast, user: userName, ts: Date.now() } });
delete toastPayload.topic;

node.warn('📱 RFID UI toast: [' + userName + '] ' + toast);

const ackDir = '/dev/shm/rfid_ack';
const ackFile = ackDir + '/ack_' + cardId;
try {
    if (!fs.existsSync(ackDir)) fs.mkdirSync(ackDir, { recursive: true });
    fs.writeFileSync(ackFile, 'ok');
    node.warn('✅ RFID ACK written for card: ' + cardId);
} catch(e) {
    node.error('Failed to write RFID ACK: ' + e.message);
}

return [victronPayload, easeePayload, goePayload, toastPayload];

const p = (msg && msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!p.authorized) return null;

const token = flow.get('easee_token');
const chargerId = p.charger || msg.chargerId;
const apiChargerId = flow.get('easee_charger');
if (!token || !apiChargerId) {
