    return null;
}

const opMode = Number(flow.get('easee_op_mode_' + chargerId) || 0);
const isCharging = (opMode === 3);
const enableValue = !isCharging;

msg.method = 'POST';
msg.url = 'https://api.easee.com/api/chargers/' + apiChargerId + '/settings';
msg.headers = {
