};
msg.payload = { enabled: enableValue };

node.status({ fill: enableValue ? 'green' : 'red', shape: 'dot', text: (enableValue ? 'Enable' : 'Disable') + ' → ' + chargerId });
return msg;

const p = (msg && msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!p.authorized) return null;
const cid = p.charger || msg.chargerId;
if (!cid.startsWith('victron')) {
