const cid = msg.chargerId;
const user = flow.get('pending_rfid_user_' + cid) || '';
node.status({ fill: 'green', shape: 'dot', text: 'OK → ' + user + ' [' + cid + ']' });
return null;

const hasFs = (typeof fs !== 'undefined' && typeof path !== 'undefined');

let notifFile = flow.get('rfid_notif_file_path');

if (hasFs && !notifFile) {
    try {
        function resolveDataDir() {
            const candidates = [
                '/home/smartev/.node-red',
                '/home/pi/.node-red',
                '/root/.node-red',
                '/data'
            ];
            if (typeof RED !== 'undefined' && RED.settings && RED.settings.userDir) {
                candidates.unshift(RED.settings.userDir);
