                        fs.mkdirSync(candidates[i], { recursive: true });
                    }
                    fs.accessSync(candidates[i], fs.constants.W_OK);
                    return candidates[i];
                } catch (e) { }
            }
            return '/home/smartev/.node-red';
        }
        const DATA_DIR = resolveDataDir();
        notifFile = path.join(DATA_DIR, 'rfid-notifications.json');
        flow.set('rfid_notif_file_path', notifFile);
    } catch (e) {
        node.error('Failed to resolve data directory: ' + e.message);
    }
}

function saveNotifications(arr) {
    if (!hasFs || !notifFile) return;
    try {
        const tmp = notifFile + '.tmp';
        fs.writeFileSync(tmp, JSON.stringify(arr, null, 2), 'utf8');
        fs.renameSync(tmp, notifFile);
    } catch(e) {
        node.error('Failed to save notifications: ' + e.message);
    }
}

let history = flow.get('rfid_notifications');
const loaded = flow.get('rfid_notifications_loaded');

if (!loaded) {
    if (hasFs && notifFile) {
        try {
            if (fs.existsSync(notifFile)) {
                const raw = fs.readFileSync(notifFile, 'utf8');
                if (raw && raw.trim()) {
                    history = JSON.parse(raw);
                    if (Array.isArray(history)) {
                        history.forEach(function(x) { if (x.seen === undefined) x.seen = true; });
                    }
                }
            }
        } catch (e) {
            node.error('Failed to load notifications: ' + e.message);
        }
    }
    if (!Array.isArray(history)) {
        history = flow.get('rfid_notifications') || [];
    }
    flow.set('rfid_notifications', history);
    flow.set('rfid_notifications_loaded', true);
} else if (!Array.isArray(history)) {
    history = [];
}

if (msg && msg.topic === 'rfid_history_clear') {
    history = [];
    flow.set('rfid_notifications', history);
    msg.payload = { type: 'rfid_history', history: history, unseenCount: 0 };
    saveNotifications(history);
    return msg;
}

if (msg && msg.topic === 'rfid_history_request') {
    const unseenCount = history.filter(function(x) { return !x.seen; }).length;
    msg.payload = { type: 'rfid_history', history: history, unseenCount: unseenCount };
    return msg;
}

if (msg && msg.topic === 'rfid_notifications_read') {
    history.forEach(function(x) { x.seen = true; });
    flow.set('rfid_notifications', history);
    saveNotifications(history);
    msg.payload = { type: 'rfid_history', history: history, unseenCount: 0 };
    return msg;
}

if (msg && msg.topic === 'rfid_multi_charger') {
    return msg;
}

if (msg && msg.topic === 'last_scanned_card') {
    msg.payload = { type: 'last_scanned_card', card_id: msg.payload.card_id, ts: Date.now() };
    return msg;
}

const payloadObj = (msg && msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const text = payloadObj.text ? String(payloadObj.text) : ((msg && msg.payload != null && typeof msg.payload !== 'object') ? String(msg.payload) : '');
if (!text) return null;

const isPrep = text.indexOf('Preparing') !== -1 || payloadObj.isPrep === true;
const isStart = text.indexOf('started') !== -1;
const isStop = text.indexOf('stopped') !== -1;

const userName = payloadObj.user || payloadObj.name || 'Unknown';

if (history.length > 0) {
    const last = history[0];
    const ageSec = (Date.now() - new Date(last.ts).getTime()) / 1000;
    if (last.text === text && last.user === userName && ageSec < 10) {
        return null;
    }
}

const now = new Date();
const strDate = now.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit' });
const stamp = strDate + ' ' + now.toLocaleTimeString('en-GB', { hour12: false });

if (!isPrep) {
    history.unshift({ text: text, user: userName, ts: now.toISOString(), time: stamp, seen: false });
    if (history.length > 100) history = history.slice(0, 100);
    flow.set('rfid_notifications', history);
    saveNotifications(history);
}

msg.payload = {
    type: 'rfid_notification',
    text: text,
    user: userName,
    time: stamp,
    history: history,
    unseenCount: history.filter(function(x) { return !x.seen; }).length,
    isPrep: isPrep,
    isStart: isStart,
    isStop: isStop
};
return msg;

if (msg.payload && msg.payload.type) {
    msg.type = msg.payload.type;
    msg.chargerId = msg.payload.chargerId;
    if (msg.payload.amp !== undefined) {
        msg.amp = msg.payload.amp;
    }
    if (msg.payload.info) {
        msg.info = msg.payload.info;
        if (typeof msg.info === 'string' && msg.info.toLowerCase().includes('error')) {
            node.warn('Poller Error [' + msg.chargerId + ']: ' + msg.info);

        }
    }
    msg.payload = msg.payload.payload;
}
return msg;

if (msg.payload && msg.payload.time_since_last_response !== undefined) {
    msg.payload.isOffline = (msg.payload.time_since_last_response > 30);
}
let cid = msg.chargerId;
if (!cid || !msg.payload || typeof msg.payload !== 'object') return msg;

let oldStates = flow.get('last_ui_states') || {};
let oldMsg = oldStates[cid] || {};
let connectedAt = oldMsg.connectedAt || 0;
let fullyChargedAt = oldMsg.fullyChargedAt || 0;
let connectedEnergy = oldMsg.connectedEnergy || 0;
let sessionEnergy = oldMsg.sessionEnergy || 0;
let lastUpdate = oldMsg.lastUpdate || Date.now();

function appendHistoryRecord(rec) {
    try {
        let dataDir = '/home/smartev/.node-red';
        if (typeof RED !== 'undefined' && RED.settings && RED.settings.userDir) {
            dataDir = RED.settings.userDir;
        } else {
            const candidates = ['/home/lefteris/.node-red', '/home/pi/.node-red', '/root/.node-red', '/data'];
            for (let i = 0; i < candidates.length; i++) {
                if (fs.existsSync(candidates[i])) { dataDir = candidates[i]; break; }
            }
        }
        const histFile = path.join(dataDir, 'charging-history.json');
        let history = [];
        if (fs.existsSync(histFile)) {
            const raw = fs.readFileSync(histFile, 'utf8');
            if (raw && raw.trim()) {
                history = JSON.parse(raw);
            }
        }
        history.push(rec);

        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        history = history.filter(function(x) {
            const time = x.connectedAt || new Date(x.timestamp).getTime();
            return time >= ninetyDaysAgo;
        });

        if (history.length > 1000) {
            history = history.slice(history.length - 1000);
        }
        fs.writeFileSync(histFile, JSON.stringify(history, null, 2), 'utf8');
    } catch(e) {
        node.error('appendHistoryRecord error: ' + e.message);
    }
}

if (msg.payload.occupied && !oldMsg.occupied) {
    connectedAt = Date.now();
    connectedEnergy = msg.payload.energy || 0;
    sessionEnergy = 0;
    lastUpdate = Date.now();

    let defaultAmp = 16;
    const smartConf = global.get('smartParkingConfig') || { CHARGERS: {} };
    if (smartConf.CHARGERS && smartConf.CHARGERS[cid] && smartConf.CHARGERS[cid].amp) {
        defaultAmp = Number(smartConf.CHARGERS[cid].amp) || 16;
    }
    msg.payload.amp = defaultAmp;
    msg.payload.targetAmp = defaultAmp;
    msg.payload.desiredAmp = defaultAmp;
}

if (oldMsg.occupied && !msg.payload.occupied) {
    let endChargeTime = (oldMsg.fullyChargedAt && oldMsg.fullyChargedAt > 0) ? oldMsg.fullyChargedAt : Date.now();
    let durationMinutes = Math.floor((endChargeTime - oldMsg.connectedAt) / 60000);
    if (durationMinutes < 0) durationMinutes = 0;

    let sessionRecord = {
        chargerId: cid,
        zoneId: oldMsg.zoneId,
        spot: oldMsg.spot,
        name: oldMsg.name || 'Unknown',
        user: oldMsg.activeUser || oldMsg.name || 'Unknown',
        connectedAt: oldMsg.connectedAt,
        disconnectedAt: Date.now(),
        durationMinutes: durationMinutes,
        energyKWh: Number(oldMsg.sessionEnergy || 0),
        timestamp: new Date().toISOString()
    };
    appendHistoryRecord(sessionRecord);
}

if (!msg.payload.occupied) {
    connectedAt = 0;
    fullyChargedAt = 0;
    connectedEnergy = 0;
    sessionEnergy = 0;
    lastUpdate = 0;
}

if (msg.payload.isCharged && !oldMsg.isCharged) fullyChargedAt = Date.now();
if (!msg.payload.isCharged) fullyChargedAt = 0;

// ★★★ FIX: Energy calculation — always track P×t as fallback ★★★
if (msg.payload.occupied) {
    // Method 1: Counter-based energy (from Modbus total kWh register)
    var counterEnergy = 0;
    if (msg.payload.energy !== undefined && msg.payload.energy > 0) {
        if (connectedEnergy === 0 && msg.payload.energy > 0) {
            connectedEnergy = msg.payload.energy;
        }
        counterEnergy = Math.max(0, msg.payload.energy - connectedEnergy);
    }

    // Method 2: P×t accumulation (always track as fallback)
    if (lastUpdate > 0) {
        var durationHours = (Date.now() - lastUpdate) / 3600000;
        if (durationHours > 0 && durationHours < 0.5) {
            sessionEnergy += (msg.payload.power || 0) * durationHours;
        }
    }
    lastUpdate = Date.now();

    // Use counter when it's working (higher = more accurate), else keep P×t
    if (counterEnergy > sessionEnergy) {
        sessionEnergy = counterEnergy;
    }
}
// ★★★ END FIX ★★★

msg.payload.connectedAt = connectedAt;
msg.payload.fullyChargedAt = fullyChargedAt;
msg.payload.connectedEnergy = connectedEnergy;
msg.payload.sessionEnergy = sessionEnergy;
msg.payload.lastUpdate = lastUpdate;

const lastWriteTime = flow.get('last_write_time_' + cid) || 0;
const lastWriteAmp = flow.get('last_write_amp_' + cid) || 0;

if (Date.now() - lastWriteTime < 8000) {
    msg.payload.amp = lastWriteAmp;
    msg.payload.targetAmp = lastWriteAmp;
    if (msg.payload.desiredAmp === undefined && oldMsg.desiredAmp !== undefined) {
        msg.payload.desiredAmp = oldMsg.desiredAmp;
    }
} else {
    if (msg.payload.amp === undefined && oldMsg.amp !== undefined) {
        msg.payload.amp = oldMsg.amp;
    }
    if (msg.payload.targetAmp === undefined && oldMsg.targetAmp !== undefined) {
        msg.payload.targetAmp = oldMsg.targetAmp;
    }
    if (msg.payload.desiredAmp === undefined && oldMsg.desiredAmp !== undefined) {
        msg.payload.desiredAmp = oldMsg.desiredAmp;
    }
}

let states = flow.get('last_ui_states') || {};
states[cid] = msg.payload;
flow.set('last_ui_states', states);

// Decide if we should write to disk to save CPU & SD card wear
let shouldWriteToDisk = false;
if (oldMsg.occupied !== msg.payload.occupied ||
    oldMsg.isOffline !== msg.payload.isOffline ||
    oldMsg.isCharged !== msg.payload.isCharged ||
    oldMsg.name !== msg.payload.name ||
    oldMsg.activeCard !== msg.payload.activeCard ||
    oldMsg.amp !== msg.payload.amp ||
    oldMsg.targetAmp !== msg.payload.targetAmp ||
    oldMsg.desiredAmp !== msg.payload.desiredAmp) {
    shouldWriteToDisk = true;
}

// Throttle periodic writes to once every 30 seconds to capture running energy/timer progression without blocking the loop
let lastDiskWrite = flow.get('last_disk_write_states_' + cid) || 0;
if (Date.now() - lastDiskWrite > 900000) {
    shouldWriteToDisk = true;
}

if (shouldWriteToDisk) {
    flow.set('last_disk_write_states_' + cid, Date.now());
    try {
        let dataDir = '/home/smartev/.node-red';
        if (typeof RED !== 'undefined' && RED.settings && RED.settings.userDir) {
            dataDir = RED.settings.userDir;
        } else {
            const candidates = ['/home/lefteris/.node-red', '/home/pi/.node-red', '/root/.node-red', '/data'];
            for (let i = 0; i < candidates.length; i++) {
                if (fs.existsSync(candidates[i])) { dataDir = candidates[i]; break; }
            }
        }
        const statesFile = path.join(dataDir, 'last-ui-states.json');
        fs.writeFileSync(statesFile + '.tmp', JSON.stringify(states, null, 2), 'utf8');
        fs.renameSync(statesFile + '.tmp', statesFile);
    } catch(e) {
        node.error('Save last ui states error: ' + e.message);
    }
}

return msg;

const cid = msg.chargerId;
const type = msg.chargerType;
const amp = Number(msg.payload.amp);
if (!amp || isNaN(amp) || amp < 6 || amp > 32) return null;

// Store last write info in flow context to lock read-back for 8 seconds
flow.set('last_write_time_' + cid, Date.now());
flow.set('last_write_amp_' + cid, amp);

node.status({ fill: 'blue', shape: 'dot', text: 'Set ' + amp + 'A on ' + cid });

if (type === 'goe' || type === 'go-e') {

    return [null, { payload: { fc: 16, unitid: 1, address: 299, value: [amp], quantity: 1 }, chargerId: cid }];
} else if (type === 'victron') {
    return [{ payload: { fc: 6, unitid: 1, address: 5016, value: amp, quantity: 1 }, chargerId: cid }, null];
}
return [null, null];

const TOTAL_POWER = global.get('TOTAL_POWER') || 35.0;
const BUFFER = 1.0;
const TARGET_LIMIT = TOTAL_POWER - BUFFER;

let states = flow.get('last_ui_states') || {};
const smartConfig = global.get('smartParkingConfig') || { CHARGERS: {} };

let total_kw = 0;
let active = [];

for (let cid in states) {
    let s = states[cid];
    if (s.occupied && !s.isOffline) {
        let kw = s.power || 0;
        total_kw += kw;
        // Use config/state amps; enforce per-charger min/max (some HW clamps e.g. 16–20A)
        let confCharger = smartConfig.CHARGERS[cid] || {};
        const type = confCharger.type || (cid.includes('victron') ? 'victron' : (cid.includes('easee') ? 'easee' : 'goe'));

        // Defaults
        const defaultMinAmp = (type === 'victron') ? 16 : 6;
        const defaultMaxAmp = (type === 'victron') ? 20 : 32;

        const minAmp = (confCharger.minAmp !== undefined && confCharger.minAmp !== null) ? Number(confCharger.minAmp) : defaultMinAmp;
        const maxAmp = (confCharger.maxAmp !== undefined && confCharger.maxAmp !== null) ? Number(confCharger.maxAmp)
                      : ((confCharger.amp !== undefined && confCharger.amp !== null) ? Number(confCharger.amp) : defaultMaxAmp);

        let desired = s.desiredAmp || s.targetAmp || maxAmp;
        if (desired > maxAmp) desired = maxAmp;
        if (desired < minAmp) desired = minAmp;

        let current = (s.amp !== undefined && s.amp !== null) ? Number(s.amp) : desired;
        if (current > maxAmp) current = maxAmp;
        if (current < minAmp) current = minAmp;

        // Rough kW-per-A estimate for minimum-feasible checks
        const kwPerAmp = (type === 'victron') ? 0.69 : 0.23;

        active.push({
            id: cid,
            state: s,
            type: type,
            currentAmp: current,
            desiredAmp: desired,
            minAmp: minAmp,
            maxAmp: maxAmp,
            kwPerAmp: kwPerAmp
        });
    }
}

if (active.length === 0) return null;


// Warn (throttled) if requested target is below physical minimum of active chargers
const minWarnLast = flow.get('dlb_min_warn_ts') || 0;
const minWarnNow = Date.now();
if (minWarnNow - minWarnLast > 15000) {
    flow.set('dlb_min_warn_ts', minWarnNow);

    let minTotalPossible = 0;
    for (let el of active) {
        const minPossible = el.minAmp * el.kwPerAmp;
        minTotalPossible += minPossible;
        if (TARGET_LIMIT < minPossible - 0.01) {
            node.warn('⚠️ DLB LIMIT TOO LOW: ' + el.id + ' min≈' + minPossible.toFixed(1) + 'kW (minAmp=' + el.minAmp + 'A). Target=' + TARGET_LIMIT.toFixed(1) + 'kW');
        }
    }
    if (active.length > 1 && TARGET_LIMIT < minTotalPossible - 0.01) {
        node.warn('⚠️ DLB LIMIT TOO LOW FOR ALL: minTotal≈' + minTotalPossible.toFixed(1) + 'kW (active=' + active.length + '). Target=' + TARGET_LIMIT.toFixed(1) + 'kW');
    }
}

let msgs = [];
let stateChanged = false;

const dlbDiagLast = flow.get('dlb_diag_ts') || 0;
const dlbNow = Date.now();
if (dlbNow - dlbDiagLast > 10000) {
    flow.set('dlb_diag_ts', dlbNow);
    node.warn('[DLB-DIAG] total=' + total_kw.toFixed(2) + 'kW target=' + TARGET_LIMIT.toFixed(2) + 'kW active=' + active.map(a => a.id + ':' + a.currentAmp + 'A(d=' + a.desiredAmp + ')').join(', '));
}

if (total_kw > TARGET_LIMIT) {
    // AGGRESSIVE reduction - proportional cut
    let reduction_factor = TARGET_LIMIT / total_kw;
    for (let el of active) {
        let new_amp = Math.floor(el.currentAmp * reduction_factor);
        if (new_amp < el.minAmp) new_amp = el.minAmp;

        if (new_amp < el.currentAmp) {
            el.state.amp = new_amp;
            if (el.state.desiredAmp === undefined) el.state.desiredAmp = el.currentAmp;
            if (el.state.targetAmp === undefined) el.state.targetAmp = el.currentAmp;
            stateChanged = true;
            node.warn('⚡ DLB CUT: ' + el.id + ' ' + el.currentAmp + 'A → ' + new_amp + 'A (total=' + total_kw.toFixed(1) + 'kW, limit=' + TARGET_LIMIT + 'kW)');
            if (new_amp === el.minAmp && total_kw > TARGET_LIMIT + 0.1) {
                node.warn('⚠️ DLB STUCK AT MIN: ' + el.id + ' minAmp=' + el.minAmp + 'A; total=' + total_kw.toFixed(1) + 'kW target=' + TARGET_LIMIT.toFixed(1) + 'kW');
            }
            msgs.push({
                chargerId: el.id,
                chargerType: el.type,
                payload: { amp: new_amp }
            });
        }
    }
} else if (total_kw < TARGET_LIMIT - 2.0) {
    // Recovery - increase +1A per cycle but check headroom
    let upgradable = active.filter(el => el.currentAmp < el.desiredAmp);
    if (upgradable.length > 0) {
        let headroom = TARGET_LIMIT - total_kw;
        for (let el of upgradable) {
            if (headroom < 0.5) break;
            let new_amp = el.currentAmp + 1;
            if (new_amp > el.desiredAmp) new_amp = el.desiredAmp;
            if (new_amp > el.maxAmp) new_amp = el.maxAmp;
            if (new_amp > el.currentAmp) {
                el.state.amp = new_amp;
                stateChanged = true;
                node.warn('⚡ DLB RAISE: ' + el.id + ' ' + el.currentAmp + 'A → ' + new_amp + 'A (headroom=' + headroom.toFixed(1) + 'kW)');
                msgs.push({
                    chargerId: el.id,
                    chargerType: el.type,
                    payload: { amp: new_amp }
                });
                headroom -= el.kwPerAmp;
            }
        }
    }
}

if (stateChanged) {
    flow.set('last_ui_states', states);
    return [msgs];
}

return null;

if (msg.topic === 'smart_config_request' ||
    msg.topic === 'cars_config_request' ||
    msg.topic === 'get_charging_history' ||
    msg.topic === 'reload_from_disk' ||
    msg.topic === 'restore_seed_config' ||
    msg.topic === 'factory_reset_config' ||
    (msg.payload && (msg.payload.type === 'smart_config' || msg.payload.type === 'cars_config'))) {
    return null;
}

const cid = msg.chargerId;
if (!cid || !msg.payload || typeof msg.payload !== 'object') {
    return null;
}

msg.payload = [
    {
        power: Number(msg.payload.power || 0),
        session_energy: Number(msg.payload.sessionEnergy || 0),
        current_limit: Number(msg.payload.amp || 16),
        is_occupied: !!msg.payload.occupied,
        is_charged: !!msg.payload.isCharged,
        is_offline: !!msg.payload.isOffline,
        online: !msg.payload.isOffline
    },
    {
        charger_id: cid,
        zone_id: msg.payload.zoneId || '',
        spot: String(msg.payload.spot || '')
    }
];

return msg;
